export const PRESS_ONE_PAGER_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Wordocious press one-pager</title>\n<style>\n  @page { size: Letter; margin: 0.5in; }\n  :root { --ink: #1f1633; --soft: #5b5170; --purple: #6d28d9; --amber: #f5a623; --tint: #f4effd; }\n  * { box-sizing: border-box; }\n  body { margin: 0; font: 11.5px/1.45 -apple-system, \"Helvetica Neue\", Arial, sans-serif; color: var(--ink); background: #fff; }\n  .page { max-width: 7.5in; margin: 0 auto; padding: 0.25in 0; }\n  header { display: flex; align-items: flex-end; justify-content: space-between; border-bottom: 4px solid var(--purple); padding-bottom: 8px; }\n  h1 { margin: 0; font-size: 30px; letter-spacing: 0.04em; color: var(--purple); font-weight: 900; }\n  .tag { font-size: 14px; font-weight: 800; color: var(--ink); text-align: right; }\n  h2 { margin: 14px 0 4px; font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--purple); font-weight: 900; }\n  p { margin: 0 0 6px; }\n  .lead { font-size: 13px; font-weight: 600; margin-top: 12px; }\n  .cols { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }\n  ul { margin: 0; padding-left: 16px; }\n  li { margin-bottom: 3px; }\n  .games { background: var(--tint); border-radius: 10px; padding: 8px 12px; }\n  .games b { color: var(--purple); }\n  .links li { list-style: none; margin-left: -16px; }\n  footer { margin-top: 14px; padding-top: 8px; border-top: 1px solid #ddd; display: flex; justify-content: space-between; gap: 12px; color: var(--soft); font-size: 10.5px; }\n  a { color: var(--purple); text-decoration: none; }\n  @media print { .page { padding: 0; } }\n</style>\n</head>\n<body>\n<div class=\"page\">\n  <header>\n    <h1>WORDOCIOUS</h1>\n    <div class=\"tag\">18 daily games. One score. Bring your family.</div>\n  </header>\n\n  <p class=\"lead\">Wordocious is a free daily puzzle app with 18 daily games, one score and a live head-to-head mode, hosted by a cast of ten letter characters. It plays the same on the web, iPhone and Android, and everyone gets the same puzzles each day, so friends and families can compare and trash-talk.</p>\n\n  <div class=\"games\">\n    <h2 style=\"margin-top:0\">The 18 daily games</h2>\n    <p><b>Eight word dailies:</b> Classic, Six, Seven, QuadWord, OctoWord, Succession, Deliverance and Gauntlet.</p>\n    <p style=\"margin-bottom:0\"><b>Ten puzzles:</b> ProperNoundle, Sudocious, Muddle, Hubbub, Crosswordocious, Kindred, Letter Ladder, Codebreaker, Spyglass and Starsweep.</p>\n  </div>\n\n  <div class=\"cols\">\n    <div>\n      <h2>What makes it different</h2>\n      <ul>\n        <li>One account, one streak and one score across all 18 games, with global and friends leaderboards for each.</li>\n        <li>Live VS: race a friend on the same puzzle, or climb the bot ladder against the ten-character cast, from Rip to the boss, Webster.</li>\n        <li>An original cast with faces, voices and costumes, plus a mascot builder.</li>\n        <li>Spoiler-free share cards for every game.</li>\n        <li>The whole app dresses for the season: Halloween Oct 17 to Oct 31, then a Thanksgiving build in November.</li>\n      </ul>\n    </div>\n    <div>\n      <h2>Free, and what Pro adds</h2>\n      <p>Every daily is free to play. Wordocious Pro is optional: $6.99 a month, $59.99 a year, or a $1 day pass. Pro adds unlimited puzzles, VS in every mode, streak shields, extra mascot items and deeper stats.</p>\n      <h2>The family origin</h2>\n      <p>We built one daily word game so our family could trash-talk each other over the same board. Then it got out of hand. Two founders, Brian Terchin and Jasson Patterson, took it from one daily to 18 games, live head-to-head and a full cast in about ten weeks.</p>\n    </div>\n  </div>\n\n  <h2>Where to play</h2>\n  <ul class=\"links\">\n    <li>Web: <a href=\"https://wordocious.com\">wordocious.com</a></li>\n    <li>iPhone and iPad: <a href=\"https://apps.apple.com/us/app/id6775966055\">apps.apple.com/us/app/id6775966055</a></li>\n    <li>Android: <a href=\"https://play.google.com/store/apps/details?id=com.wordocious.app\">play.google.com/store/apps/details?id=com.wordocious.app</a></li>\n  </ul>\n\n  <footer>\n    <div><b>Press contact:</b> Jasson Patterson, co-founder, <a href=\"mailto:jp@pattersonlp.com\">jp@pattersonlp.com</a><br>Press link: <a href=\"https://wordocious.com/go/press\">wordocious.com/go/press</a></div>\n    <div style=\"text-align:right\">Screenshots and cast art on request.<br>Wordocious is made by ShowLoud, LLC.</div>\n  </footer>\n</div>\n</body>\n</html>\n";
